import{_ as t,o as a,a as r,a2 as o}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md","lastUpdated":1789331268000}'),i={name:"architecture/overview.md"};function n(d,e,s,l,c,h){return a(),r("div",null,e[0]||(e[0]=[o('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>This document provides a comprehensive overview of Bagisto&#39;s architecture and core principles, designed to help developers understand the framework&#39;s structure and implementation approach.</p><h2 id="technology-stack" tabindex="-1">Technology Stack <a class="header-anchor" href="#technology-stack" aria-label="Permalink to &quot;Technology Stack&quot;">​</a></h2><p>Bagisto is built on a modern, robust technology stack leveraging proven <a href="https://en.wikipedia.org/wiki/Open_source" target="_blank" rel="noreferrer">Open Source</a> technologies:</p><ul><li><strong><a href="https://php.net" target="_blank" rel="noreferrer">PHP</a></strong> - Server-side programming language</li><li><strong><a href="https://laravel.com" target="_blank" rel="noreferrer">Laravel</a></strong> - PHP framework for web application development</li><li><strong><a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue.js</a></strong> - Progressive JavaScript framework for user interfaces</li><li><strong><a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a></strong> - Utility-first CSS framework for styling</li><li><strong><a href="https://vitejs.dev/" target="_blank" rel="noreferrer">Vite</a></strong> - Asset bundler with hot module replacement</li></ul><p>The exact versions depend on the release line you run:</p><table tabindex="0"><thead><tr><th></th><th>Bagisto 2.5</th><th>Bagisto 2.4</th></tr></thead><tbody><tr><td>PHP</td><td>8.4</td><td>8.3 or 8.4</td></tr><tr><td>Laravel</td><td>13</td><td>12</td></tr><tr><td>Vue.js</td><td>3.5</td><td>3.5</td></tr><tr><td>Tailwind CSS</td><td>4 (CSS-first configuration)</td><td>3 (<code>tailwind.config.js</code>)</td></tr><tr><td>Vite</td><td>6</td><td>6</td></tr><tr><td>Test runner</td><td>Pest 5</td><td>Pest 3</td></tr><tr><td>Databases</td><td>MySQL 8, MariaDB 10.11, PostgreSQL 16</td><td>MySQL 8, MariaDB 10.11</td></tr></tbody></table><p>On Bagisto 2.5 all three databases are first-class and covered by the CI matrix; the <a href="./../advanced/database-compatibility.html">Database Compatibility</a> page explains the <code>db_grammar()</code> abstraction that keeps package code portable across them. Bagisto 2.4 supports MySQL and MariaDB only.</p><h2 id="core-architecture-principles" tabindex="-1">Core Architecture Principles <a class="header-anchor" href="#core-architecture-principles" aria-label="Permalink to &quot;Core Architecture Principles&quot;">​</a></h2><h3 id="dual-interface-design" tabindex="-1">Dual Interface Design <a class="header-anchor" href="#dual-interface-design" aria-label="Permalink to &quot;Dual Interface Design&quot;">​</a></h3><p>Bagisto provides a comprehensive e-commerce solution with two primary interfaces:</p><ul><li><strong>Customer Frontend</strong> - Public-facing storefront for customer interactions, served by the <code>Shop</code> package and skinned by <a href="./../theme-development/getting-started.html">themes</a></li><li><strong>Administrative Backend</strong> - Management interface for store administration and configuration, served by the <code>Admin</code> package</li></ul><p>Both are ordinary Blade applications with Vue components mounted inside them; there is no separate single-page application to build.</p><h3 id="modular-package-structure" tabindex="-1">Modular Package Structure <a class="header-anchor" href="#modular-package-structure" aria-label="Permalink to &quot;Modular Package Structure&quot;">​</a></h3><p>The framework follows a modular architecture where each core functionality is encapsulated in a dedicated Laravel package under <code>packages/Webkul/</code>, providing a clean separation of concerns and enabling easy customization and extension. Each package registers a service provider in <code>bootstrap/providers.php</code> and, when it has models, a Concord module provider in <code>config/concord.php</code>. The <a href="./backend.html">Backend</a> page lists every package that ships with Bagisto.</p><h3 id="component-based-frontend" tabindex="-1">Component-Based Frontend <a class="header-anchor" href="#component-based-frontend" aria-label="Permalink to &quot;Component-Based Frontend&quot;">​</a></h3><p>Bagisto utilizes Vue.js built-in components to create:</p><ul><li>Reusable UI elements, exposed to Blade as the <a href="./../theme-development/blade-components.html">components</a> of the <code>shop</code> and <code>admin</code> namespaces</li><li>Interactive user interfaces</li><li>Dynamic content rendering</li><li>Seamless user experience</li></ul><h3 id="event-driven-architecture" tabindex="-1">Event-Driven Architecture <a class="header-anchor" href="#event-driven-architecture" aria-label="Permalink to &quot;Event-Driven Architecture&quot;">​</a></h3><p>The framework implements a comprehensive event system that:</p><ul><li>Triggers events across application lifecycle (<a href="./../advanced/event-listeners.html">Event Listeners</a>)</li><li>Enables custom functionality through event listeners</li><li>Provides hooks for third-party integrations, including <a href="./../advanced/view-render-events.html">view render events</a> for injecting markup into existing templates</li><li>Supports extensibility without core modifications</li></ul><h3 id="extension-points-at-a-glance" tabindex="-1">Extension points at a glance <a class="header-anchor" href="#extension-points-at-a-glance" aria-label="Permalink to &quot;Extension points at a glance&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You want to</th><th>Read</th></tr></thead><tbody><tr><td>Add a feature with its own tables, admin pages and routes</td><td><a href="./../package-development/getting-started.html">Package Development</a></td></tr><tr><td>Change how the storefront looks</td><td><a href="./../theme-development/getting-started.html">Theme Development</a></td></tr><tr><td>Add a carrier, a gateway or a product type</td><td><a href="./../shipping-method-development/getting-started.html">Shipping</a>, <a href="./../payment-method-development/getting-started.html">Payment</a>, <a href="./../product-type-development/getting-started.html">Product Type</a> development</td></tr><tr><td>React to something the core does</td><td><a href="./../advanced/event-listeners.html">Event Listeners</a></td></tr><tr><td>Replace a core model or repository</td><td><a href="./../package-development/models.html#overriding-core-models-optional">Models</a></td></tr><tr><td>Talk to the store from outside</td><td><a href="./../api/introduction.html">REST and GraphQL APIs</a>, <a href="./../ai/webmcp.html">WebMCP</a></td></tr></tbody></table>',23)]))}const u=t(i,[["render",n]]);export{m as __pageData,u as default};
